    def save_scheduled_report(
        self,
        *,
        name: str,
        kind: Literal["instrument_usage", "spend", "project_status"],
        period: Literal["previous_week", "previous_month", "last_7_days", "last_30_days"],
        frequency: Literal["daily", "weekly", "monthly"],
        recipient_user_ids: List[str],
        id: Union[Optional[str], Unset] = UNSET,
        project_id: Union[Optional[str], Unset] = UNSET,
        open_hours: Union[float, Unset] = UNSET,
        weekday: Union[int, Unset] = UNSET,
        month_day: Union[int, Unset] = UNSET,
        send_hour: Union[int, Unset] = UNSET,
        time_zone: Union[str, Unset] = UNSET,
        active: Union[bool, Unset] = UNSET,
    ) -> Dict[str, "JsonValue"]:
        """
        Schedule a report, or change a schedule

        Emails a report on a rhythm with the detail attached as CSV. Pass an existing `p_id` to change a schedule. Recipients must be members of the workspace and are checked again at send time. Needs permission to edit the schema, or to manage instruments for the usage report, and a personal token.

        Scopes: facility:write.

        ``POST /api/db/rpc/save_scheduled_report``
        """
        body: Dict[str, Any] = {}
        body["p_name"] = name
        body["p_kind"] = kind
        body["p_period"] = period
        body["p_frequency"] = frequency
        body["p_recipient_user_ids"] = recipient_user_ids
        if not isinstance(id, Unset):
            body["p_id"] = id
        if not isinstance(project_id, Unset):
            body["p_project_id"] = project_id
        if not isinstance(open_hours, Unset):
            body["p_open_hours"] = open_hours
        if not isinstance(weekday, Unset):
            body["p_weekday"] = weekday
        if not isinstance(month_day, Unset):
            body["p_month_day"] = month_day
        if not isinstance(send_hour, Unset):
            body["p_send_hour"] = send_hour
        if not isinstance(time_zone, Unset):
            body["p_time_zone"] = time_zone
        if not isinstance(active, Unset):
            body["p_active"] = active
        return self._call("save_scheduled_report", body)  # type: ignore[no-any-return]

    def save_search(
        self,
        *,
        name: str,
        query: str,
        facets: Union[Dict[str, "JsonValue"], Unset] = UNSET,
        visibility: Union[str, Unset] = UNSET,
        arguments: Union[Dict[str, "JsonValue"], Unset] = UNSET,
    ) -> "SavedSearchesRow":
        """
        Save a search

        Saves a search for the person the token belongs to (needs a personal token). `p_visibility` is `private` (default) or `workspace`; anyone except a viewer can share. Saving the same search again replaces it. A person keeps their newest 20 private searches; a workspace keeps up to 100 shared ones with unique names. `p_arguments` takes the inputs `search` takes (`p_query`, `p_filter`, `p_sort`, `p_kind`, `p_status`, `p_project_id`, `p_owner_id`, `p_date_from`, `p_date_to`, `p_result_type`, `p_include_archived`).

        Scopes: projects:write.

        ``POST /api/db/rpc/save_search``
        """
        body: Dict[str, Any] = {}
        body["p_name"] = name
        body["p_query"] = query
        if not isinstance(facets, Unset):
            body["p_facets"] = facets
        if not isinstance(visibility, Unset):
            body["p_visibility"] = visibility
        if not isinstance(arguments, Unset):
            body["p_arguments"] = arguments
        return self._call("save_search", body)  # type: ignore[no-any-return]

    def search(
        self,
        *,
        query: Union[str, Unset] = UNSET,
        project_id: Union[Optional[str], Unset] = UNSET,
        kind: Union[Optional[str], Unset] = UNSET,
        status: Union[Optional[str], Unset] = UNSET,
        owner_id: Union[Optional[str], Unset] = UNSET,
        date_from: Union[Optional[str], Unset] = UNSET,
        date_to: Union[Optional[str], Unset] = UNSET,
        limit: Union[int, Unset] = UNSET,
        offset: Union[int, Unset] = UNSET,
    ) -> List[Dict[str, Any]]:
        """
        Workspace search

        All filters optional. `p_limit` clamped to 1–100 (default 20). `p_offset` default 0. Empty `p_query` browses. Returns a JSON array; `total_count` is repeated on each row.

        Scopes: projects:read.

        ``POST /api/db/rpc/search``
        """
        body: Dict[str, Any] = {}
        if not isinstance(query, Unset):
            body["p_query"] = query
        if not isinstance(project_id, Unset):
            body["p_project_id"] = project_id
        if not isinstance(kind, Unset):
            body["p_kind"] = kind
        if not isinstance(status, Unset):
            body["p_status"] = status
        if not isinstance(owner_id, Unset):
            body["p_owner_id"] = owner_id
        if not isinstance(date_from, Unset):
            body["p_date_from"] = date_from
        if not isinstance(date_to, Unset):
            body["p_date_to"] = date_to
        if not isinstance(limit, Unset):
            body["p_limit"] = limit
        if not isinstance(offset, Unset):
            body["p_offset"] = offset
        return self._call("search", body)  # type: ignore[no-any-return]

