    async def update_webhook_subscription(
        self,
        *,
        workspace_id: str,
        subscription_id: str,
        url: Union[str, Unset] = UNSET,
        event_types: Union[List["JsonValue"], Unset] = UNSET,
        description: Union[str, Unset] = UNSET,
        status: Union[str, Unset] = UNSET,
        max_retries: Union[int, Unset] = UNSET,
        failure_threshold: Union[int, Unset] = UNSET,
        rate_limit_per_minute: Union[int, Unset] = UNSET,
    ) -> Union["WebhookSubscriptionsRow", List["WebhookSubscriptionsRow"]]:
        """
        Update a webhook subscription

        Updates URL, event types, description, status, retry config, or rate limit (null leaves the rate limit unchanged). Re-enabling a disabled/paused subscription resets consecutive_failures.

        Scopes: webhooks:write.

        ``POST /api/db/rpc/update_webhook_subscription``
        """
        body: Dict[str, Any] = {}
        body["p_workspace_id"] = workspace_id
        body["p_subscription_id"] = subscription_id
        if not isinstance(url, Unset):
            body["p_url"] = url
        if not isinstance(event_types, Unset):
            body["p_event_types"] = event_types
        if not isinstance(description, Unset):
            body["p_description"] = description
        if not isinstance(status, Unset):
            body["p_status"] = status
        if not isinstance(max_retries, Unset):
            body["p_max_retries"] = max_retries
        if not isinstance(failure_threshold, Unset):
            body["p_failure_threshold"] = failure_threshold
        if not isinstance(rate_limit_per_minute, Unset):
            body["p_rate_limit_per_minute"] = rate_limit_per_minute
        return await self._call("update_webhook_subscription", body)  # type: ignore[no-any-return]

